// Category A — almost no behavior (purely static display), owns the look.
// A small <kbd> badge ("⌘K") that displays keyboard shortcuts in menu items, etc.
import { Keyboard as AriaKeyboard } from "react-aria-components";
import type { ComponentProps, Ref } from "react";
import "./Keyboard.css";

// react-aria-components doesn't export a standalone `KeyboardProps` type;
// derive it from the component itself.
type AriaKeyboardProps = Omit<ComponentProps<typeof AriaKeyboard>, "ref">;

export interface KeyboardProps extends Omit<AriaKeyboardProps, "className"> {
  /** Additional class (optional). sd-keyboard is always preserved. */
  className?: string;
  /** Forwarded to the underlying <kbd> DOM node. */
  ref?: Ref<HTMLElement>;
}

export function Keyboard({ className, ref, ...props }: KeyboardProps) {
  return (
    <AriaKeyboard
      {...props}
      ref={ref}
      className={className ? `sd-keyboard sd-type-code-medium ${className}` : "sd-keyboard sd-type-code-medium"}
    />
  );
}

.sd-keyboard {
  display: inline-flex;
  align-items: center;
  padding-inline: var(--sd-keyboard-padding-inline);
  color: var(--sd-keyboard-foreground);
  background: var(--sd-keyboard-background);
  border: var(--sd-keyboard-border-width) solid var(--sd-keyboard-border);
  border-radius: var(--sd-keyboard-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}
